 5	public class BalancedParentheses {
 6	    private static final String DEFAULT_SAMPLE = "[()()]{}";
 7	
 8	    private BalancedParentheses() {}
 9	
10	    public static boolean isBalanced(String s) {
11	        return isBalanced((CharSequence) s);
12	    }
13	
14	    public static boolean isBalanced(CharSequence input) {
15	        Objects.requireNonNull(input, "input");
16	        BalanceChecker checker = new BalanceChecker();
17	
18	        for (int i = 0; i < input.length(); i++) {
19	            if (!checker.accept(input.charAt(i))) {
20	                return false;
21	            }
22	        }
23	
24	        return checker.isBalanced();
25	    }
26	
27	    public static void main(String[] args) {
28	        String s = args.length > 0 ? args[0] : DEFAULT_SAMPLE;
29	        System.out.println((isBalanced(s) ? "true" : "false"));
30	    }
31	
32	    private static final class BalanceChecker {
33	        private final Deque<Character> expectedClosings = new ArrayDeque<>();
34	
35	        private boolean accept(char candidate) {
36	            BracketToken token = BracketToken.from(candidate);
37	            if (token == null) {
38	                return true;
39	            }
40	
41	            if (token.isOpening()) {
42	                expectedClosings.push(token.expectedClosing());
43	                return true;
44	            }
45	
46	            return !expectedClosings.isEmpty() && expectedClosings.pop() == token.expectedClosing();
47	        }
48	
49	        private boolean isBalanced() {
50	            return expectedClosings.isEmpty();
51	        }
52	    }
53	
54	    private enum BracketToken {
55	        OPEN_PAREN(')', true),
56	        OPEN_BRACE('}', true),
57	        OPEN_BRACKET(']', true),
58	        CLOSE_PAREN(')', false),
59	        CLOSE_BRACE('}', false),
60	        CLOSE_BRACKET(']', false);
61	
62	        private final char expectedClosing;
63	        private final boolean opening;
64	
65	        BracketToken(char expectedClosing, boolean opening) {
66	            this.expectedClosing = expectedClosing;
67	            this.opening = opening;
68	        }
69	
70	        private static BracketToken from(char candidate) {
71	            return switch (candidate) {
72	                case '(' -> OPEN_PAREN;
73	                case '{' -> OPEN_BRACE;
74	                case '[' -> OPEN_BRACKET;
75	                case ')' -> CLOSE_PAREN;
76	                case '}' -> CLOSE_BRACE;
77	                case ']' -> CLOSE_BRACKET;
78	                default -> null;
79	            };
80	        }
81	
82	        private boolean isOpening() {
83	            return opening;
84	        }
85	
86	        private char expectedClosing() {
87	            return expectedClosing;
88	        }
89	    }
