 7	public class BalancedParentheses {
 8	    private static final String DEFAULT_SAMPLE = "[()()]{}";
 9	    private static final BracketProfile DEFAULT_BRACKETS = BracketProfile.standard();
10	
11	    private BalancedParentheses() {}
12	
13	    public static boolean isBalanced(CharSequence input) {
14	        Objects.requireNonNull(input, "input");
15	        return new BalanceChecker(DEFAULT_BRACKETS).check(input);
16	    }
17	
18	    public static void main(String[] args) {
19	        String s = args.length > 0 ? args[0] : DEFAULT_SAMPLE;
20	        System.out.println((isBalanced(s) ? "true" : "false"));
21	    }
22	
23	    private static final class BalanceChecker {
24	        private final BracketProfile bracketProfile;
25	        private final Deque<Character> expectedClosings = new ArrayDeque<>();
26	
27	        private BalanceChecker(BracketProfile bracketProfile) {
28	            this.bracketProfile = bracketProfile;
29	        }
30	
31	        private boolean check(CharSequence input) {
32	            for (int i = 0; i < input.length(); i++) {
33	                if (!accept(input.charAt(i))) {
34	                    return false;
35	                }
36	            }
37	
38	            return expectedClosings.isEmpty();
39	        }
40	
41	        private boolean accept(char candidate) {
42	            Character expectedClosing = bracketProfile.expectedClosingFor(candidate);
43	            if (expectedClosing != null) {
44	                expectedClosings.push(expectedClosing);
45	                return true;
46	            }
47	
48	            if (!bracketProfile.isClosingBracket(candidate)) {
49	                return true;
50	            }
51	
52	            return !expectedClosings.isEmpty() && expectedClosings.pop() == candidate;
53	        }
54	    }
55	
56	    private static final class BracketProfile {
57	        private final Map<Character, Character> openingToClosing;
58	        private final Set<Character> closingBrackets;
59	
60	        private BracketProfile(Map<Character, Character> openingToClosing, Set<Character> closingBrackets) {
61	            this.openingToClosing = openingToClosing;
62	            this.closingBrackets = closingBrackets;
63	        }
64	
65	        private static BracketProfile standard() {
66	            Map<Character, Character> openingToClosing = Map.of(
67	                '(', ')',
68	                '{', '}',
69	                '[', ']'
70	            );
71	            return new BracketProfile(openingToClosing, Set.copyOf(openingToClosing.values()));
72	        }
73	
74	        private Character expectedClosingFor(char candidate) {
75	            return openingToClosing.get(candidate);
76	        }
77	
78	        private boolean isClosingBracket(char candidate) {
79	            return closingBrackets.contains(candidate);
80	        }
81	    }
82	}

